body.script:
//
// Mobile Menu
document.addEventListener('DOMContentLoaded', function() {
    const mobileMenuBtn = document.getElementById('mobile-menu-btn');
    const sidebarWrapper = document.getElementById('sidebar-wrapper');
    const mobileOverlay = document.getElementById('mobile-overlay');

    function toggleMobileMenu() {
        const isOpen = !sidebarWrapper.classList.contains('-translate-x-full');
        if (isOpen) {
            sidebarWrapper.classList.add('-translate-x-full');
            mobileOverlay.classList.add('hidden');
            mobileOverlay.classList.remove('opacity-100');
            document.body.style.overflow = '';
        } else {
            sidebarWrapper.classList.remove('-translate-x-full');
            mobileOverlay.classList.remove('hidden');
            setTimeout(() => mobileOverlay.classList.add('opacity-100'), 0);
            document.body.style.overflow = 'hidden';
        }
    }

    if (mobileMenuBtn) {
        mobileMenuBtn.addEventListener('click', toggleMobileMenu);
    }
    if (mobileOverlay) {
        mobileOverlay.addEventListener('click', toggleMobileMenu);
    }
});

// JS Sorting
let currentSort = { col: -1, dir: 'asc' };

function sortTable(n, type) {
    const table = document.getElementById("move-table");
    if (!table) return;
    const tbody = table.querySelector("tbody");
    const rows = Array.from(tbody.querySelectorAll("tr"));

    if (currentSort.col === n) {
        currentSort.dir = currentSort.dir === 'asc' ? 'desc' : 'asc';
    } else {
        currentSort.col = n;
        currentSort.dir = 'asc';
    }

    rows.sort((a, b) => {
        let x = a.cells[n].getAttribute('data-value');
        let y = b.cells[n].getAttribute('data-value');

        if (type === 'number') {
            x = parseFloat(x) || 0;
            y = parseFloat(y) || 0;
        } else {
            x = (x || '').toLowerCase();
            y = (y || '').toLowerCase();
        }

        if (x === y) return 0;
        if (currentSort.dir === 'asc') {
            return x > y ? 1 : -1;
        } else {
            return x < y ? 1 : -1;
        }
    });

    tbody.innerHTML = "";
    rows.forEach(row => tbody.appendChild(row));
    updateSortIcons(n);
}

function sortCombined(n1, n2, n3) {
    const table = document.getElementById("move-table");
    if (!table) return;
    const tbody = table.querySelector("tbody");
    const rows = Array.from(tbody.querySelectorAll("tr"));
    const key = `combined_${n1}_${n2}_${n3}`;

    if (currentSort.col === key) {
        currentSort.dir = currentSort.dir === 'asc' ? 'desc' : 'asc';
    } else {
        currentSort.col = key;
        currentSort.dir = 'asc';
    }

    rows.sort((a, b) => {
        const valA = (parseFloat(a.cells[n1].getAttribute('data-value')) || 0) + 
                     (parseFloat(a.cells[n2].getAttribute('data-value')) || 0) +
                     (parseFloat(a.cells[n3].getAttribute('data-value')) || 0);
        const valB = (parseFloat(b.cells[n1].getAttribute('data-value')) || 0) + 
                     (parseFloat(b.cells[n2].getAttribute('data-value')) || 0) +
                     (parseFloat(b.cells[n3].getAttribute('data-value')) || 0);

        if (valA === valB) return 0;
        if (currentSort.dir === 'asc') return valA > valB ? 1 : -1;
        return valA < valB ? 1 : -1;
    });

    tbody.innerHTML = "";
    rows.forEach(row => tbody.appendChild(row));
    updateSortIcons(key);
}

function updateSortIcons(activeKey) {
    document.querySelectorAll('.sort-icon').forEach(icon => {
        icon.classList.remove('sort-active');
        icon.innerHTML = 'swap_vert';
    });
}
//
